#!/usr/bin/env python3

"""A small task tracker."""

import sys

DEFAULT_PRIORITY = 5
DIGITS = "0123456789"


class Task:
    def __init__(self, id, title):
        self.id = id
        self.title = title
        self.done = False
        self.priority = DEFAULT_PRIORITY


def find(tasks, id):
    for task in tasks:
        if task.id == id:
            return task
    return None


def sort_key(task):
    return (task.priority, task.id)


def main():
    lines = open(sys.argv[1], "rb").read().decode("utf-8").rstrip("\n").split("\n")
    tasks = []
    next_id = 1

    for line in lines:
        if line.strip() == "":
            continue
        parts = line.split(" ", 1)
        command = parts[0]
        rest = parts[1] if len(parts) > 1 else ""

        if command == "add":
            tasks.append(Task(next_id, rest))
            print(f"added {next_id}")
            next_id = next_id + 1
        elif command == "done":
            id = int(rest)
            task = find(tasks, id)
            if task is None:
                print(f"no such task {id}")
            else:
                task.done = True
                print(f"done {id}")
        elif command == "prio":
            id_text, _, p = rest.partition(" ")
            id = int(id_text)
            task = find(tasks, id)
            if task is None:
                print(f"no such task {id}")
            elif len(p) != 1 or p not in DIGITS:
                print(f"bad priority {p}")
            else:
                task.priority = int(p)
                print(f"prio {id} {p}")
        elif command == "list":
            everything = rest == "all"
            for task in sorted(tasks, key=sort_key):
                if everything:
                    mark = "x" if task.done else "-"
                    print(f"{mark} {task.id} {task.title}")
                elif not task.done:
                    print(f"{task.id} {task.title}")
        else:
            print(f"? {command}")


main()

